function validate(state){return root.CoopJourney.validateDeck(state,root.CoopData,root.CoopGeometry,root.CoopTargets);}
function commit(next,expected,title){if(raw()!==expected)throw Error('다른 화면에서 덱이 변경되었습니다. 최신 덱을 불러온 뒤 다시 비교하세요.');validate(next);const previousJournal=localStorage.getItem(JOURNAL),after=JSON.stringify(next),journal={before:expected,after,title,undone:false};write(JOURNAL,journal);try{localStorage.setItem(KEY,after);}catch(e){if(previousJournal===null)localStorage.removeItem(JOURNAL);else localStorage.setItem(JOURNAL,previousJournal);throw e;}if(expected){try{const previous=JSON.parse(expected);if(previous?.version!==2||!Array.isArray(previous.cells)||!previous.you?.perDemon||!previous.partner?.perDemon)throw Error('이전 덱 형식');if(previous.cells.length)validate(previous);const history=read('stack-lab-undo-v1')||[];history.push(expected);write('stack-lab-undo-v1',history.slice(-30));}catch{}}notify();message(title+' 저장 완료 · 변경 전 상태로 되돌릴 수 있습니다.');}
function travel(redo=false){const j=read(JOURNAL);if(!j||j.undone!==redo)throw Error('복원할 변경이 없습니다.');const expected=redo?j.before:j.after;if(raw()!==expected)throw Error('이후에 덱이 변경되었습니다. 배치 화면의 되돌리기를 사용하세요.');const value=redo?j.after:j.before;if(value===null)localStorage.removeItem(KEY);else localStorage.setItem(KEY,value);j.undone=!redo;write(JOURNAL,j);notify();message(redo?'변경을 다시 적용했습니다.':'변경 전 덱을 복원했습니다.');}
function safely(fn){return()=>{try{fn();}catch(e){message(e.message||'저장 공간을 사용할 수 없습니다.');if(dialog?.open){const status=dialog.querySelector('[role="status"]');if(status)status.textContent=e.message;}}};}
function open(title){if(!dialog){dialog=el('dialog',undefined,'experience-dialog');dialog.setAttribute('aria-labelledby','experience-dialog-title');document.body.append(dialog);dialog.addEventListener('close',()=>returnFocus?.isConnected&&returnFocus.focus());}if(!dialog.open)returnFocus=document.activeElement;dialog.replaceChildren();const header=el('header'),h=el('h2',title);h.id='experience-dialog-title';header.append(h,button('닫기',()=>dialog.close()));dialog.append(header);const status=el('p');status.setAttribute('role','status');dialog.append(status);dialog.showModal();return dialog;}
function describe(row){return row.changes.map(c=>{if(c.type==='gem'){const gem=g=>g?.id?(dictionary[root.CoopData.GEM_BY_ID.get(g.id)?.name]||root.CoopData.GEM_BY_ID.get(g.id)?.name||g.id)+' '+g.grade:'미장착';return(c.slot+1)+'번 보석 '+gem(c.from)+' → '+gem(c.to);}if(c.type==='unit')return label(c.from)+' → '+label(c.to);return({level:'레벨',lib:'해방',stack:'입력 스택'}[c.type]||c.type)+' '+c.from+' → '+c.to;}).join(' / ');}
